const hoy = $now.toFormat('yyyy-LL-dd');
const leads = $('Leer Leads').all().map(i=>i.json).filter(l=>l && l.ID_Lead);
const ds = s => String(s||'').slice(0,10);
const by = (k) => leads.reduce((a,l)=>{const v=String(l[k]||'sin');a[v]=(a[v]||0)+1;return a;},{});
const porEstado = by('Estado');
const porICP = by('Micro_ICP');
const activos = ['contactado','respondio','agendado','lead_handoff','nurturing'];
const sinSig = leads.filter(l=>activos.includes(l.Estado) && !ds(l.Fecha_Siguiente_Paso)).map(l=>l.Empresa);
const vencidos = leads.filter(l=>l.Estado==='contactado' && ds(l.Fecha_Siguiente_Paso) && ds(l.Fecha_Siguiente_Paso)<hoy).map(l=>`${l.Empresa} (${ds(l.Fecha_Siguiente_Paso)})`);
const prox = leads.filter(l=>ds(l.Fecha_Siguiente_Paso)>=hoy).map(l=>({e:l.Empresa,f:ds(l.Fecha_Siguiente_Paso)})).sort((a,b)=>a.f.localeCompare(b.f)).slice(0,15);
const m = {
  fecha: hoy, total: leads.length,
  por_estado: porEstado, por_micro_icp: porICP,
  contactadas: porEstado['contactado']||0,
  respondio: porEstado['respondio']||0,
  agendado: porEstado['agendado']||0,
  lead_handoff: porEstado['lead_handoff']||0,
  tarjetas_listas: (porEstado['no_contactado']||0)+(porEstado['pendiente']||0),
  nurturing: porEstado['nurturing']||0,
  alertas: { sin_siguiente_paso: sinSig.slice(0,15), seguimientos_vencidos: vencidos.slice(0,15) },
  proximos: prox
};
const system = [
'<identidad>Analista comercial senior de ACCES GROUP. Reporte ejecutivo diario claro y accionable, solo con los datos provistos, sin inventar.</identidad>',
'<reglas>Espanol ejecutivo. HTML simple (h2,h3,ul,table). Incluye: (1) Marcador del dia, (2) Embudo por Estado y por Micro-ICP, (3) Alertas (sin siguiente paso, seguimientos vencidos), (4) Proximos seguimientos, (5) 3 recomendaciones de Siguiente Mejor Accion priorizadas por impacto (meta $2.5M/mes, cobertura 3.3x). Sin firma.</reglas>',
'<salida>Devuelve SOLO el HTML del reporte, sin ``` ni texto fuera del HTML.</salida>'
].join('\n');
const user = 'Fecha: '+hoy+'\nMarcador (JSON):\n'+JSON.stringify(m,null,2)+'\n\nGenera el reporte ejecutivo en HTML.';
return [{ json: { hoy, system, user } }];

